mapper.select:
select * from (SELECT new.*, num * price AS totalPrice FROM (select fzname,allocateid,kufang_change1.cid p_id,kufang_change1.cname p_name,cnum num,tid,date,original_price price from kufang_change1,kufang_goods
where kufang_change1.cname=kufang_goods.cname) new) new3


        AND fzname LIKE CONCAT('%',#{fzname},'%')


        AND p_name LIKE CONCAT('%',#{p_name},'%')


        AND date<#{date1}


        AND date>=#{date2}
